/**
 * La autorización canónica de una ejecución local gestionada (ADR-THYROX-007,
 * enmienda 1.16.0).
 *
 * Todo trabajo local que thyrox gestiona —crear un banco, escribir o editar
 * archivos, instalar dependencias, compilar, probar, sondear, servir o
 * cuantizar un modelo, commitear— corre dentro de un contenedor de ejecución
 * que esta primitiva materializa. El anfitrión es plano de control: compone la
 * autorización, la entrega aquí y observa el resultado.
 *
 * La autorización es la del contenedor. Una decisión de dominio la COMPONE,
 * no la hereda: un `ExecutionGrant` de modelo (model-artifacts) se traduce en
 * una autorización `model-runtime` con referencia al grant; este paquete es
 * neutral y no conoce modelos. La identidad de un runtime de modelo ya
 * materializado es la `ExecutionUnit` de model-scheduling.
 *
 * El repositorio puede montarse de escritura: la mutación llega al árbol real,
 * pero el proceso que la hace vive en el contenedor, no en el shell que la
 * pidió.
 */

import { inspectContainerState, materializeContainer, runJobWithOutput, type JobOutput } from './containerRun.js'
import type { PodmanExecutor } from './podmanExecutor.js'
import { requireValidOwner, type ContainerOwner, type WorkerContainerSpec } from './workerContainerLifecycle.js'
import {
  InvalidWorkerResourceProfileError,
  workerResourceLimitArgv,
  type WorkerNetworkMode,
  type WorkerPublishedPort,
  type WorkerResourceMount,
} from './workerResourceProfile.js'

export const EXECUTION_KINDS = [
  'workbench',
  'build',
  'test',
  'probe',
  'infrastructure',
  'model-runtime',
  'quantization',
  'registry-operation',
  'maintenance',
] as const

export type ExecutionKind = (typeof EXECUTION_KINDS)[number]

export const EXECUTION_KIND_LABEL_KEY = 'thyrox.execution-kind'
export const EXECUTION_REFERENCE_LABEL_KEY = 'thyrox.execution-reference'
export const EXECUTION_ID_LABEL_KEY = 'thyrox.execution-id'
const EXECUTION_LABEL_KEYS = [EXECUTION_KIND_LABEL_KEY, EXECUTION_REFERENCE_LABEL_KEY, EXECUTION_ID_LABEL_KEY]

/** La cita durable de una tarea; el ordinal del board reinicia por sesión y no identifica nada. */
export const TASK_CITATION_PATTERN = /^TASK-[A-Z]+-\d{4}$/
const EXECUTION_ID_PATTERN = /^[A-Za-z0-9][A-Za-z0-9_.-]{0,62}$/
const REFERENCE_ID_PATTERN = /^[A-Za-z0-9][A-Za-z0-9_.:-]*$/
const SECRET_NAME_PATTERN = /^[a-z0-9][a-z0-9_.-]*$/
const SECRET_TARGET_PATTERN = /^[A-Za-z0-9][A-Za-z0-9_.-]*$/

/** Lo que autoriza la ejecución: la tarea, el grant de modelo o el recurso de infraestructura. */
export type ExecutionReference =
  | { kind: 'task'; citation: string }
  | { kind: 'grant'; grantId: string }
  | { kind: 'infrastructure'; resource: string }

export type ExecutionResources = {
  cpus: number
  memoryMib: number
  pidsLimit: number
}

/** Un secreto de Podman por su nombre; se monta como archivo, su valor nunca pasa por aquí. */
export type ExecutionSecret = {
  name: string
  target: string
}

export type ExecutionAuthorization = {
  /** Nombra el contenedor (`thyrox-worker-<executionId>`). */
  executionId: string
  reference: ExecutionReference
  owner: ContainerOwner
  kind: ExecutionKind
  image: string
  /** Sin comando, el de la imagen. */
  command?: readonly string[]
  /** Sin directorio, el de la imagen; declarado, vive dentro de un montaje. */
  workdir?: string
  mounts: readonly WorkerResourceMount[]
  resources: ExecutionResources
  network: WorkerNetworkMode
  /** Sólo valores públicos: quedan en `podman inspect`. */
  environment?: Readonly<Record<string, string>>
  secrets?: readonly ExecutionSecret[]
  publishedPorts?: readonly WorkerPublishedPort[]
  /** Dispositivos en forma CDI. */
  devices?: readonly string[]
  /** Etiquetas propias del dueño; no reescriben las de la ejecución. */
  labels?: Readonly<Record<string, string>>
  /** Rutas que el trabajo produce; cada una bajo un montaje de escritura. */
  outputs?: readonly string[]
  /** Instante, en milisegundos Unix, a partir del cual la autorización no vale. */
  expiresAt?: number
}

/** La autorización no se puede materializar; nombra el campo. */
export class InvalidExecutionAuthorizationError extends Error {
  readonly field: string

  constructor(field: string, message: string) {
    super(message)
    this.name = 'InvalidExecutionAuthorizationError'
    this.field = field
  }
}

function refuse(field: string, message: string): never {
  throw new InvalidExecutionAuthorizationError(field, message)
}

function isUnder(path: string, root: string): boolean {
  const prefix = root.endsWith('/') ? root : `${root}/`
  return path === root || path.startsWith(prefix)
}

function isKnownKind(kind: string): kind is ExecutionKind {
  return (EXECUTION_KINDS as readonly string[]).includes(kind)
}

/** El tipo de referencia que cada tipo de ejecución exige. */
function expectedReferenceKind(kind: ExecutionKind): ExecutionReference['kind'] {
  if (kind === 'model-runtime') return 'grant'
  if (kind === 'infrastructure') return 'infrastructure'
  return 'task'
}

function referenceLabel(reference: ExecutionReference): string {
  if (reference.kind === 'task') return `task:${reference.citation}`
  if (reference.kind === 'grant') return `grant:${reference.grantId}`
  return `infrastructure:${reference.resource}`
}

function requireReference(kind: ExecutionKind, reference: ExecutionReference): void {
  const expected = expectedReferenceKind(kind)
  if (reference.kind !== expected) refuse('reference', `una ejecución ${kind} se autoriza por ${expected}, recibido: ${reference.kind}`)
  if (reference.kind === 'task' && !TASK_CITATION_PATTERN.test(reference.citation)) {
    refuse('reference', `la tarea se cita como TASK-<CAPA>-NNNN, recibido: ${reference.citation}`)
  }
  const identifier = referenceLabel(reference).slice(reference.kind.length + 1)
  if (!REFERENCE_ID_PATTERN.test(identifier)) refuse('reference', `identificador de referencia inválido: ${identifier}`)
}

function requireOwner(owner: ContainerOwner): void {
  try {
    requireValidOwner(owner)
  } catch (error) {
    refuse('owner', error instanceof Error ? error.message : String(error))
  }
}

function requireWorkdir(authorization: ExecutionAuthorization): void {
  const { workdir } = authorization
  if (workdir === undefined) return
  if (!authorization.mounts.some(mount => isUnder(workdir, mount.destination))) {
    refuse('workdir', `el directorio de trabajo ${workdir} no vive dentro de ningún montaje`)
  }
}

function requireOutputsWritable(authorization: ExecutionAuthorization): void {
  for (const output of authorization.outputs ?? []) {
    const writable = authorization.mounts.some(mount => mount.mode === 'rw' && isUnder(output, mount.destination))
    if (!writable) refuse('outputs', `la salida ${output} no vive bajo un montaje de escritura`)
  }
}

function requireSecretsByName(secrets: readonly ExecutionSecret[]): void {
  secrets.forEach((secret, index) => {
    if (!SECRET_NAME_PATTERN.test(secret.name)) refuse(`secrets[${index}].name`, `nombre de secreto inválido: ${secret.name}`)
    if (!SECRET_TARGET_PATTERN.test(secret.target)) refuse(`secrets[${index}].target`, `destino de secreto inválido: ${secret.target}`)
  })
}

function requireOwnLabels(labels: Readonly<Record<string, string>>): void {
  const overridden = Object.keys(labels).filter(key => EXECUTION_LABEL_KEYS.includes(key))
  if (overridden.length > 0) refuse('labels', `las etiquetas ${overridden.join(', ')} son de la ejecución, no del dueño`)
}

/** Valida la autorización completa; rehúsa en el primer campo inválido, nombrándolo. */
export function validateExecutionAuthorization(authorization: ExecutionAuthorization, now = Date.now()): void {
  if (!EXECUTION_ID_PATTERN.test(authorization.executionId)) refuse('executionId', `id de ejecución inválido: ${authorization.executionId}`)
  if (!isKnownKind(authorization.kind)) refuse('kind', `tipo de ejecución desconocido: ${authorization.kind}`)
  requireReference(authorization.kind, authorization.reference)
  requireOwner(authorization.owner)
  if (!authorization.image) refuse('image', 'la imagen no puede estar vacía')
  if (authorization.command !== undefined && !authorization.command[0]) refuse('command', 'un comando declarado no puede estar vacío')
  requireWorkdir(authorization)
  requireOutputsWritable(authorization)
  requireSecretsByName(authorization.secrets ?? [])
  requireOwnLabels(authorization.labels ?? {})
  if (authorization.expiresAt !== undefined && authorization.expiresAt <= now) refuse('expiresAt', 'la autorización expiró')
}

function resourceArgv(authorization: ExecutionAuthorization): string[] {
  try {
    return workerResourceLimitArgv({
      ...authorization.resources,
      network: authorization.network,
      readOnlyRootfs: false,
      mounts: [...authorization.mounts],
      environment: authorization.environment,
      publishedPorts: authorization.publishedPorts,
      devices: authorization.devices,
    })
  } catch (error) {
    if (error instanceof InvalidWorkerResourceProfileError) refuse(error.field, error.message)
    throw error
  }
}

function workdirArgv(workdir: string | undefined): string[] {
  return workdir === undefined ? [] : ['--workdir', workdir]
}

function secretArgv(secrets: readonly ExecutionSecret[]): string[] {
  return secrets.flatMap(secret => ['--secret', `${secret.name},type=mount,target=${secret.target}`])
}

/** Traduce una autorización válida al contenedor que la primitiva materializa. No ejecuta nada. */
export function executionContainerSpec(authorization: ExecutionAuthorization, now = Date.now()): WorkerContainerSpec {
  validateExecutionAuthorization(authorization, now)
  return {
    workerId: authorization.executionId,
    image: authorization.image,
    owner: authorization.owner,
    resourceArgv: [...resourceArgv(authorization), ...workdirArgv(authorization.workdir), ...secretArgv(authorization.secrets ?? [])],
    command: authorization.command,
    labels: {
      ...authorization.labels,
      [EXECUTION_KIND_LABEL_KEY]: authorization.kind,
      [EXECUTION_REFERENCE_LABEL_KEY]: referenceLabel(authorization.reference),
      [EXECUTION_ID_LABEL_KEY]: authorization.executionId,
    },
  }
}

/** Corre el trabajo autorizado hasta que termine y retira su contenedor; devuelve su veredicto y su diagnóstico. */
export async function runExecution(podman: PodmanExecutor, authorization: ExecutionAuthorization, now = Date.now()): Promise<JobOutput> {
  return runJobWithOutput(podman, executionContainerSpec(authorization, now))
}

/**
 * La unidad materializada: la única identidad de una ejecución gestionada,
 * cualquiera que sea su clase. Un dominio la especializa —la unidad de un
 * modelo añade su grant y su endpoint— sin definir otra.
 */
export interface ExecutionUnit {
  readonly unitId: string
  readonly kind: ExecutionKind
  readonly reference: ExecutionReference
  readonly owner: ContainerOwner
  readonly containerName: string
  readonly containerId: string
  /** El cgroup del contenedor visto desde el anfitrión, si Podman lo informa. */
  readonly cgroup?: string
  /** PIDs del proceso principal vistos desde el anfitrión; vacío si no corre. */
  readonly hostPids: readonly number[]
  /** Instante ISO 8601 en UTC. */
  readonly createdAt: string
}

/**
 * Crea, arranca e inspecciona el contenedor de una ejecución de vida larga y
 * devuelve su `ExecutionUnit`; no lo espera ni lo retira. Un fallo nombra la
 * etapa (`create`, `start`, `inspect`) y, a partir de `start`, el contenedor
 * queda creado para su dueño.
 */
export async function materializeExecution(
  podman: PodmanExecutor,
  authorization: ExecutionAuthorization,
  now = Date.now(),
): Promise<ExecutionUnit> {
  const { containerName, containerId } = await materializeContainer(podman, executionContainerSpec(authorization, now))
  const state = await inspectContainerState(podman, containerName)
  return {
    unitId: authorization.executionId,
    kind: authorization.kind,
    reference: authorization.reference,
    owner: authorization.owner,
    containerName,
    containerId,
    ...(state.cgroup === undefined ? {} : { cgroup: state.cgroup }),
    hostPids: state.hostPids,
    createdAt: new Date(now).toISOString(),
  }
}

/**
 * Correr un contenedor hasta que termine, señalarlo y exportar lo que dejó
 * (ADR-THYROX-007, TASK-THYROX-0667): la parte de «ejecutar» de la
 * primitiva, sin máquina de estados, generaciones ni recuperación — eso es
 * del dueño.
 *
 * El orden que este módulo garantiza es exportar ANTES de limpiar: `podman
 * cp` sólo lee de un contenedor que todavía existe, así que una limpieza
 * adelantada pierde el artefacto sin error visible en el llamador.
 */

import { basename, join } from 'node:path'

import type { PodmanCommandResult, PodmanExecutor } from './podmanExecutor.js'
import { isLockCollision, lockCollisionRemedy } from './podmanLockCollision.js'
import {
  createWorkerContainerArgv,
  removeWorkerContainerArgv,
  workerContainerName,
  type WorkerContainerSpec,
} from './workerContainerLifecycle.js'

export type ContainerRunStage = 'create' | 'start' | 'inspect' | 'wait' | 'logs' | 'signal' | 'export'

/** Mensaje base del fallo: la etapa, el sujeto y lo que Podman dijo. */
function failureMessage(stage: ContainerRunStage, subject: string, result: PodmanCommandResult): string {
  return `falló la etapa ${stage} sobre ${subject}: ${result.stderr.trim() || `exit ${result.exitCode}`}`
}

/**
 * Un paso de la ejecución falló; nombra la etapa y lo que Podman dijo. Si fue
 * una colisión de locks, lo marca y añade el remedio: no se reintenta en
 * silencio, porque reintentar no reasigna el lock.
 */
export class ContainerRunError extends Error {
  readonly stage: ContainerRunStage
  readonly lockCollision: boolean

  constructor(stage: ContainerRunStage, subject: string, result: PodmanCommandResult) {
    const lockCollision = isLockCollision(result.stderr)
    const message = failureMessage(stage, subject, result)
    super(lockCollision ? `${message}. ${lockCollisionRemedy(subject)}` : message)
    this.name = 'ContainerRunError'
    this.stage = stage
    this.lockCollision = lockCollision
  }
}

const EXIT_CODE_PATTERN = /^-?\d+$/

async function requireSuccess(
  podman: PodmanExecutor,
  stage: ContainerRunStage,
  subject: string,
  args: readonly string[],
): Promise<PodmanCommandResult> {
  const result = await podman.run(args)
  if (result.exitCode !== 0) throw new ContainerRunError(stage, subject, result)
  return result
}

/** Lee el código que imprime `podman wait`; una salida que no es un entero no se lee como 0. */
function parseWaitExitCode(name: string, result: PodmanCommandResult): number {
  const printed = result.stdout.trim()
  if (!EXIT_CODE_PATTERN.test(printed)) {
    throw new ContainerRunError('wait', name, { ...result, stderr: `salida de wait ilegible: «${printed}»` })
  }
  return Number(printed)
}

/** Un contenedor creado y arrancado: su nombre y el id que imprimió `podman create`. */
export type MaterializedContainer = {
  containerName: string
  containerId: string
}

/** Lo que `podman inspect` dice del contenedor en el anfitrión: su proceso y su cgroup. */
export type InspectedContainerState = {
  hostPids: readonly number[]
  cgroup?: string
}

/** Podman informa `Pid: 0` de un contenedor sin proceso. */
const NOT_RUNNING_PID = 0

/**
 * Inspecciona un contenedor y devuelve su proceso y su cgroup vistos desde el
 * anfitrión. Un fallo de Podman o una salida ilegible es la etapa `inspect`:
 * una unidad sin identidad no se publica como materializada.
 */
export async function inspectContainerState(podman: PodmanExecutor, containerName: string): Promise<InspectedContainerState> {
  const result = await podman.run(['inspect', '--format', 'json', containerName])
  if (result.exitCode !== 0) throw new ContainerRunError('inspect', containerName, result)
  let first: { State?: { Pid?: unknown; CgroupPath?: unknown } } | undefined
  try {
    const entries: unknown = JSON.parse(result.stdout)
    first = Array.isArray(entries) ? (entries[0] as typeof first) : undefined
  } catch {
    first = undefined
  }
  if (!first?.State) {
    throw new ContainerRunError('inspect', containerName, { ...result, stderr: `salida ilegible: «${result.stdout.trim()}»` })
  }
  const { Pid: pid, CgroupPath: cgroup } = first.State
  return {
    hostPids: typeof pid === 'number' && pid !== NOT_RUNNING_PID ? [pid] : [],
    ...(typeof cgroup === 'string' && cgroup !== '' ? { cgroup } : {}),
  }
}

/**
 * Crea y arranca el contenedor sin esperarlo: la materialización de una unidad
 * de vida larga. Es el único sitio del árbol que emite `create` y `start`.
 * Si `start` falla, el contenedor queda creado y el error nombra la etapa:
 * retirarlo es decisión de su dueño.
 */
export async function materializeContainer(podman: PodmanExecutor, spec: WorkerContainerSpec): Promise<MaterializedContainer> {
  const containerName = workerContainerName(spec.workerId)
  const created = await requireSuccess(podman, 'create', containerName, createWorkerContainerArgv(spec))
  await requireSuccess(podman, 'start', containerName, ['start', containerName])
  return { containerName, containerId: created.stdout.trim() }
}

type CompletedContainer = { containerId: string; exitCode: number }

/** Materializa y espera el contenedor; devuelve el id que imprimió `podman create` y el código de su proceso. */
async function runAndIdentify(podman: PodmanExecutor, spec: WorkerContainerSpec): Promise<CompletedContainer> {
  const { containerName, containerId } = await materializeContainer(podman, spec)
  const exitCode = parseWaitExitCode(containerName, await requireSuccess(podman, 'wait', containerName, ['wait', containerName]))
  return { containerId, exitCode }
}

/** Crea, arranca y espera el contenedor; devuelve el código de salida de su proceso. No lo retira. */
export async function runToCompletion(podman: PodmanExecutor, spec: WorkerContainerSpec): Promise<number> {
  return (await runAndIdentify(podman, spec)).exitCode
}

/**
 * El resultado de un trabajo: su veredicto y su diagnóstico, no sus datos.
 *
 * - `exitCode` es el veredicto del proceso principal.
 * - `stdout` y `stderr` son diagnóstico, cada uno de su flujo (medido con el
 *   driver `k8s-file`: `podman logs` no los mezcla). No son un canal de
 *   datos: lo que un trabajo produce lo escribe en un montaje declarado, y
 *   quien lo invoca lo lee de ahí.
 * - `containerName` nombra al contenedor que corrió, con las etiquetas de su
 *   dueño, para correlacionar el diagnóstico con su medida y su barrido.
 * - `containerId` es el id que imprimió `podman create`: el que nombra el
 *   cgroup `libpod-<id>` de cada proceso de la unidad.
 */
export type JobOutput = {
  exitCode: number
  stdout: string
  stderr: string
  containerName: string
  containerId: string
}

/**
 * Corre el contenedor hasta que termine y devuelve su veredicto y su
 * diagnóstico, leído con `podman logs` antes de retirarlo. La limpieza ocurre
 * siempre, también si una etapa falla.
 */
export async function runJobWithOutput(podman: PodmanExecutor, spec: WorkerContainerSpec): Promise<JobOutput> {
  const name = workerContainerName(spec.workerId)
  try {
    const { containerId, exitCode } = await runAndIdentify(podman, spec)
    const logs = await requireSuccess(podman, 'logs', name, ['logs', name])
    return { exitCode, stdout: logs.stdout, stderr: logs.stderr, containerName: name, containerId }
  } finally {
    await podman.run(removeWorkerContainerArgv(name))
  }
}

/** Envía `signal` al proceso principal del contenedor (p. ej. SIGTERM para un apagado ordenado). */
export async function signalContainer(podman: PodmanExecutor, name: string, signal: NodeJS.Signals): Promise<void> {
  await requireSuccess(podman, 'signal', name, ['kill', '--signal', signal, name])
}

/** Copia cada ruta del contenedor a `hostDir` con su nombre base; devuelve las rutas en el anfitrión. */
export async function exportArtifacts(
  podman: PodmanExecutor,
  name: string,
  containerPaths: readonly string[],
  hostDir: string,
): Promise<string[]> {
  const exported: string[] = []
  for (const containerPath of containerPaths) {
    const hostPath = join(hostDir, basename(containerPath))
    await requireSuccess(podman, 'export', `${name}:${containerPath}`, ['cp', `${name}:${containerPath}`, hostPath])
    exported.push(hostPath)
  }
  return exported
}

export type ArtifactRequest = {
  containerPaths: readonly string[]
  hostDir: string
}

export type JobOutcome = {
  exitCode: number
  artifacts: string[]
}

/**
 * Corre el contenedor hasta que termine, exporta lo pedido y sólo entonces
 * lo retira. La limpieza ocurre siempre —también si correr o exportar
 * falla— y nunca antes de la exportación.
 */
export async function runJobAndCollect(
  podman: PodmanExecutor,
  spec: WorkerContainerSpec,
  artifacts: ArtifactRequest,
): Promise<JobOutcome> {
  const name = workerContainerName(spec.workerId)
  try {
    const exitCode = await runToCompletion(podman, spec)
    const exported = await exportArtifacts(podman, name, artifacts.containerPaths, artifacts.hostDir)
    return { exitCode, artifacts: exported }
  } finally {
    await podman.run(removeWorkerContainerArgv(name))
  }
}

