/**
 * Contrato del perfil de límites de recursos de un worker de Podman
 * (ADR-THYROX-007 Regla 2, TASK-THYROX-0615).
 *
 * Cada bandera que este módulo compone ya se midió contra su control en
 * `src/lib/podman_capabilities.sh` (`--pids-limit`, `--memory`, `--cpus`,
 * `--network none`, `--read-only`, montajes `:ro`). Aquí sólo vive el
 * CONTRATO del perfil —su validación y su traducción a argv—, nunca la
 * ejecución: el `PodmanWorkerManager` que crea y lanza contenedores es
 * trabajo futuro, no de este archivo.
 */

/**
 * `host` existe porque, medido en el contenedor remoto, el proxy de salida
 * escucha en el loopback del anfitrión (`127.0.0.1`) y ni `bridge` ni
 * `slirp4netns` lo alcanzan. Su costo: el trabajo ve TODO servicio del
 * loopback del anfitrión (Redis, Ollama, el proxy local). Por eso nunca es
 * el default y se declara sólo para trabajos sin credencial cuyo único
 * destino de red es el exterior.
 */
export type WorkerNetworkMode = 'none' | 'bridge' | 'host'
export type WorkerMountMode = 'ro' | 'rw'

export type WorkerResourceMount = {
  source: string
  destination: string
  mode: WorkerMountMode
}

export type WorkerResourceProfile = {
  cpus: number
  memoryMib: number
  pidsLimit: number
  network: WorkerNetworkMode
  readOnlyRootfs: boolean
  mounts: WorkerResourceMount[]
  /**
   * Variables del proceso del trabajo. Su valor queda en `Config.Env` de
   * `podman inspect` (medido 2026-09-29, `repositoryJobProfile.ts`), así que
   * sólo admite valores públicos: un nombre de credencial se rehúsa.
   */
  environment?: Readonly<Record<string, string>>
  /**
   * Puertos del contenedor publicados en el anfitrión. Sólo en loopback
   * (`127.0.0.1`): un servicio de un worker nunca escucha en la red del
   * anfitrión. Se emiten como `-p 127.0.0.1:<host>:<contenedor>`.
   */
  publishedPorts?: readonly WorkerPublishedPort[]
  /**
   * Dispositivos concedidos, en forma CDI (`nvidia.com/gpu=<uuid>`). Una ruta
   * de `/dev` se rehúsa: el dispositivo lo nombra el grant, no el anfitrión.
   */
  devices?: readonly string[]
}

export type WorkerPublishedPort = {
  hostAddress: '127.0.0.1'
  hostPort: number
  containerPort: number
}

const KNOWN_NETWORK_MODES: readonly WorkerNetworkMode[] = ['none', 'bridge', 'host']
const ENVIRONMENT_NAME_PATTERN = /^[A-Za-z_][A-Za-z0-9_]*$/
const CREDENTIAL_NAME_PATTERN = /(TOKEN|SECRET|PASSWORD|PASSWD|KEY|CREDENTIAL)/i
const KNOWN_MOUNT_MODES: readonly WorkerMountMode[] = ['ro', 'rw']
const LOOPBACK_HOST_ADDRESS = '127.0.0.1'
const MIN_PORT = 1
const MAX_PORT = 65_535
/** La red que publica puertos: `none` no tiene a dónde y `host` no lo necesita. */
const PORT_PUBLISHING_NETWORK: WorkerNetworkMode = 'bridge'
/** Nombre CDI de un dispositivo: `<vendor>/<clase>=<nombre>` (`nvidia.com/gpu=<uuid>`). */
const CDI_DEVICE_PATTERN = /^[A-Za-z0-9][A-Za-z0-9._-]*\/[A-Za-z0-9][A-Za-z0-9._-]*=[A-Za-z0-9][A-Za-z0-9._:-]*$/

/**
 * El perfil más restrictivo medido: sin red, rootfs de sólo lectura, sin
 * montajes declarados. Relajar cualquiera de los tres es explícito en el
 * perfil que se declare — nunca el default silencioso.
 */
export const DEFAULT_WORKER_RESOURCE_PROFILE: WorkerResourceProfile = {
  cpus: 1,
  memoryMib: 1024,
  pidsLimit: 128,
  network: 'none',
  readOnlyRootfs: true,
  mounts: [],
}

/** Un campo del perfil no pasó su validación; nombra el campo, nunca lo omite en silencio. */
export class InvalidWorkerResourceProfileError extends Error {
  readonly field: string

  constructor(field: string, message: string) {
    super(message)
    this.name = 'InvalidWorkerResourceProfileError'
    this.field = field
  }
}

function requirePositiveNumber(field: string, value: number): void {
  if (!Number.isFinite(value) || value <= 0) {
    throw new InvalidWorkerResourceProfileError(field, `${field} debe ser un número > 0, recibido: ${value}`)
  }
}

function requirePositiveInteger(field: string, value: number): void {
  if (!Number.isInteger(value) || value < 1) {
    throw new InvalidWorkerResourceProfileError(field, `${field} debe ser un entero >= 1, recibido: ${value}`)
  }
}

function requireKnownNetwork(network: WorkerNetworkMode): void {
  if (!KNOWN_NETWORK_MODES.includes(network)) {
    throw new InvalidWorkerResourceProfileError('network', `red desconocida: ${network}`)
  }
}

function requireValidMount(mount: WorkerResourceMount, index: number): void {
  const field = `mounts[${index}]`
  if (!mount.source) {
    throw new InvalidWorkerResourceProfileError(`${field}.source`, 'el origen del montaje no puede estar vacío')
  }
  if (!mount.destination.startsWith('/')) {
    throw new InvalidWorkerResourceProfileError(
      `${field}.destination`,
      `el destino del montaje debe ser una ruta absoluta, recibido: ${mount.destination}`,
    )
  }
  if (!KNOWN_MOUNT_MODES.includes(mount.mode)) {
    throw new InvalidWorkerResourceProfileError(`${field}.mode`, `modo de montaje desconocido: ${mount.mode}`)
  }
}

/** Valida el perfil completo; rehúsa en el primer campo inválido, nombrándolo. */
export function validateWorkerResourceProfile(profile: WorkerResourceProfile): void {
  requirePositiveNumber('cpus', profile.cpus)
  requirePositiveNumber('memoryMib', profile.memoryMib)
  requirePositiveInteger('pidsLimit', profile.pidsLimit)
  requireKnownNetwork(profile.network)
  profile.mounts.forEach((mount, index) => requireValidMount(mount, index))
  Object.keys(profile.environment ?? {}).forEach(requirePublicEnvironmentName)
  requireValidPublishedPorts(profile)
  profile.devices?.forEach(requireCdiDevice)
}

function isValidPort(port: number): boolean {
  return Number.isInteger(port) && port >= MIN_PORT && port <= MAX_PORT
}

function requireValidPublishedPorts(profile: WorkerResourceProfile): void {
  const ports = profile.publishedPorts ?? []
  if (ports.length > 0 && profile.network !== PORT_PUBLISHING_NETWORK) {
    throw new InvalidWorkerResourceProfileError(
      'publishedPorts',
      `publicar puertos exige red ${PORT_PUBLISHING_NETWORK}, el perfil declara ${profile.network}`,
    )
  }
  ports.forEach(requireValidPublishedPort)
}

function requireValidPublishedPort(port: WorkerPublishedPort, index: number): void {
  const field = `publishedPorts.${index}`
  if (port.hostAddress !== LOOPBACK_HOST_ADDRESS) {
    throw new InvalidWorkerResourceProfileError(`${field}.hostAddress`, `sólo se publica en ${LOOPBACK_HOST_ADDRESS}, recibido: ${port.hostAddress}`)
  }
  if (!isValidPort(port.hostPort)) {
    throw new InvalidWorkerResourceProfileError(`${field}.hostPort`, `puerto fuera de ${MIN_PORT}–${MAX_PORT}: ${port.hostPort}`)
  }
  if (!isValidPort(port.containerPort)) {
    throw new InvalidWorkerResourceProfileError(`${field}.containerPort`, `puerto fuera de ${MIN_PORT}–${MAX_PORT}: ${port.containerPort}`)
  }
}

function requireCdiDevice(device: string, index: number): void {
  if (!CDI_DEVICE_PATTERN.test(device)) {
    throw new InvalidWorkerResourceProfileError(`devices.${index}`, `el dispositivo debe ir en forma CDI <vendor>/<clase>=<nombre>, recibido: ${device}`)
  }
}

function requirePublicEnvironmentName(name: string): void {
  const field = `environment.${name}`
  if (!ENVIRONMENT_NAME_PATTERN.test(name)) {
    throw new InvalidWorkerResourceProfileError(field, `nombre de variable inválido: ${name}`)
  }
  if (CREDENTIAL_NAME_PATTERN.test(name)) {
    throw new InvalidWorkerResourceProfileError(field, `${name} nombra una credencial y su valor quedaría en podman inspect`)
  }
}

function cpuLimitArgv(cpus: number): string[] {
  return ['--cpus', String(cpus)]
}

function memoryLimitArgv(memoryMib: number): string[] {
  return ['--memory', `${memoryMib}m`]
}

function pidsLimitArgv(pidsLimit: number): string[] {
  return ['--pids-limit', String(pidsLimit)]
}

function networkArgv(network: WorkerNetworkMode): string[] {
  return ['--network', network]
}

function rootfsArgv(readOnlyRootfs: boolean): string[] {
  return readOnlyRootfs ? ['--read-only', '--read-only-tmpfs=false'] : []
}

function environmentArgv(environment: Readonly<Record<string, string>>): string[] {
  return Object.keys(environment).sort().flatMap(name => ['--env', `${name}=${environment[name]}`])
}

function publishedPortArgv(port: WorkerPublishedPort): string[] {
  return ['-p', `${port.hostAddress}:${port.hostPort}:${port.containerPort}`]
}

function deviceArgv(device: string): string[] {
  return ['--device', device]
}

function mountArgv(mount: WorkerResourceMount): string[] {
  return ['-v', `${mount.source}:${mount.destination}:${mount.mode}`]
}

/**
 * Traduce un perfil validado al argv de límites para `podman create`/`run`
 * — no ejecuta nada, sólo compone el argv (mismo contrato que
 * `thyrox_infrastructure_create_argv` en `src/lib/infrastructure.sh`: un
 * perfil inválido rehúsa antes de emitir ningún argumento).
 */
export function workerResourceLimitArgv(profile: WorkerResourceProfile): string[] {
  validateWorkerResourceProfile(profile)
  return [
    ...cpuLimitArgv(profile.cpus),
    ...memoryLimitArgv(profile.memoryMib),
    ...pidsLimitArgv(profile.pidsLimit),
    ...networkArgv(profile.network),
    ...rootfsArgv(profile.readOnlyRootfs),
    ...profile.mounts.flatMap(mountArgv),
    ...environmentArgv(profile.environment ?? {}),
    ...(profile.publishedPorts ?? []).flatMap(publishedPortArgv),
    ...(profile.devices ?? []).flatMap(deviceArgv),
  ]
}

/**
 * La verificación de un artefacto publicado, ejecutada como trabajo de la
 * primitiva de Podman (ADR-THYROX-007, TASK-THYROX-0728).
 *
 * El trabajo prueba lo que un consumidor externo vería: no monta el
 * almacenamiento de Podman de esta sesión ni recibe credencial alguna. Lee
 * el registry de forma anónima, materializa cada blob en su montaje de
 * trabajo y deja su veredicto en `verification.json` de ese montaje: la
 * salida estándar del contenedor es diagnóstico, no canal de datos.
 *
 * El intérprete se monta de sólo lectura desde el anfitrión, igual que el
 * repositorio, así que la imagen sólo aporta la libc. La composición pasa por
 * la autorización canónica (`registry-operation`, con la cita de su tarea):
 * el verificador no compone por spec ni alcanza ninguna función interna de la
 * primitiva.
 */
import { mkdir, readFile, rm } from 'node:fs/promises'
import { join } from 'node:path'

import { runExecution, type ExecutionAuthorization } from '@thyrox/podman-execution/executionAuthorization.ts'
import type { PodmanExecutor } from '@thyrox/podman-execution/podmanExecutor.ts'
import type { ContainerOwner } from '@thyrox/podman-execution/workerContainerLifecycle.ts'
import type { WorkerResourceProfile } from '@thyrox/podman-execution/workerResourceProfile.ts'

import type { ArtifactLocation, PinnedArtifact } from './artifactRegistry.js'
import type { ArtifactVerifier, VerificationOutcome } from './artifactVerifier.js'
import { jobNetworkProfile, type JobEgress } from './jobEgress.js'

export const VERIFICATION_REPORT_NAME = 'verification.json'

/** La cita de la tarea que autoriza la operación de registry; el llamador puede declarar otra. */
export const DEFAULT_VERIFICATION_TASK_CITATION = 'TASK-THYROX-0728'

const CONTAINER_BUN = '/usr/local/bin/bun'
const CONTAINER_REPOSITORY = '/w'
const CONTAINER_SCRATCH = '/scratch'
const VERIFY_ENTRY = `${CONTAINER_REPOSITORY}/src/packages/artifact-registry/bin/verifyArtifact.ts`

export interface PodmanJobVerifierOptions {
  readonly podman: PodmanExecutor
  /** Imagen del trabajo, ya resuelta a un ID o digest inmutable. */
  readonly image: string
  readonly bunPath: string
  readonly repositoryRoot: string
  /** Directorio del anfitrión donde el trabajo materializa blobs; su disco lo admitió el llamador. */
  readonly scratchDir: string
  readonly registryUrl: string
  readonly egress: JobEgress
  readonly owner: ContainerOwner
  readonly workerId: string
  readonly limits: Pick<WorkerResourceProfile, 'cpus' | 'memoryMib' | 'pidsLimit'>
  /** Cita de la tarea que autoriza la verificación; por defecto, la del flujo que la define. */
  readonly taskCitation?: string
}

/**
 * La verificación compuesta en la autorización canónica: clase
 * `registry-operation` con la cita de su tarea, la red que decide el egress y
 * los montajes de siempre —intérprete y repositorio de sólo lectura, scratch
 * de escritura—.
 */
export function verificationAuthorization(options: PodmanJobVerifierOptions, pinned: PinnedArtifact, location: ArtifactLocation): ExecutionAuthorization {
  const network = jobNetworkProfile(options.egress)
  return {
    executionId: options.workerId,
    reference: { kind: 'task', citation: options.taskCitation ?? DEFAULT_VERIFICATION_TASK_CITATION },
    owner: options.owner,
    kind: 'registry-operation',
    image: options.image,
    command: [
      CONTAINER_BUN, VERIFY_ENTRY,
      '--registry', options.registryUrl,
      '--repository', location.repository,
      '--tag', location.tag,
      '--digest', pinned.digest,
      '--work-dir', `${CONTAINER_SCRATCH}/blobs`,
      '--report', `${CONTAINER_SCRATCH}/${VERIFICATION_REPORT_NAME}`,
    ],
    mounts: [
      { source: options.bunPath, destination: CONTAINER_BUN, mode: 'ro' },
      { source: options.repositoryRoot, destination: CONTAINER_REPOSITORY, mode: 'ro' },
      { source: options.scratchDir, destination: CONTAINER_SCRATCH, mode: 'rw' },
      ...network.mounts,
    ],
    resources: options.limits,
    network: network.network,
    environment: { ...network.environment, HOME: `${CONTAINER_SCRATCH}/home`, TMPDIR: `${CONTAINER_SCRATCH}/tmp` },
  }
}

async function readReport(path: string): Promise<VerificationOutcome | undefined> {
  try {
    return JSON.parse(await readFile(path, 'utf8')) as VerificationOutcome
  } catch {
    return undefined
  }
}

export function createPodmanJobVerifier(options: PodmanJobVerifierOptions): ArtifactVerifier {
  return {
    async verify(pinned, location) {
      await rm(options.scratchDir, { recursive: true, force: true })
      await Promise.all(['home', 'tmp'].map(name => mkdir(join(options.scratchDir, name), { recursive: true })))
      try {
        const job = await runExecution(options.podman, verificationAuthorization(options, pinned, location))
        const report = await readReport(join(options.scratchDir, VERIFICATION_REPORT_NAME))
        if (report) return report
        return {
          status: 'unverified',
          result: { status: 'job_failed', exitCode: job.exitCode, detail: `${job.containerName} no dejó veredicto: ${job.stderr.trim().slice(-400)}` },
        }
      } finally {
        await rm(options.scratchDir, { recursive: true, force: true })
      }
    },
  }
}

