    ...overrides,
  })
}

function refusedField(candidate: ExecutionAuthorization, now?: number): string {
  try {
    validateExecutionAuthorization(candidate, now)
    return 'accepted'
  } catch (error) {
    if (error instanceof InvalidExecutionAuthorizationError) return error.field
    throw error
  }
}

function recordingPodman(calls: string[][], responses: Partial<Record<string, PodmanCommandResult>> = {}): PodmanExecutor {
  return {
    async run(args) {
      calls.push([...args])
      const verb = args[0] ?? ''
      const fallback = verb === 'create' ? 'c0ffee\n' : verb === 'wait' ? '3\n' : verb === 'logs' ? 'hola\n' : ''
      return responses[verb] ?? { exitCode: 0, stdout: fallback, stderr: '' }
    },
  }
}

describe('ExecutionAuthorization', () => {
  test('una autorización de tarea completa se acepta', () => {
    expect(refusedField(authorization())).toBe('accepted')
  })

  test('una autorización de modelo, sin comando ni directorio, se acepta', () => {
    expect(refusedField(modelAuthorization())).toBe('accepted')
  })

  test('la tarea se cita con su forma durable, no con el ordinal del board', () => {
    expect(refusedField(authorization({ reference: { kind: 'task', citation: '#99' } }))).toBe('reference')
  })

  test('un runtime de modelo se autoriza por un grant, no por una tarea', () => {
    expect(refusedField(modelAuthorization({ reference: { kind: 'task', citation: 'TASK-THYROX-0001' } }))).toBe('reference')
  })

  test('un trabajo de tarea no se autoriza por un grant', () => {
    expect(refusedField(authorization({ reference: { kind: 'grant', grantId: 'g1' } }))).toBe('reference')
  })

  test('el tipo de ejecución es uno de los declarados', () => {
    expect(refusedField(authorization({ kind: 'shell' as never }))).toBe('kind')
  })

  test('un comando declarado no puede estar vacío', () => {
    expect(refusedField(authorization({ command: [] }))).toBe('command')
  })

  test('un directorio de trabajo declarado vive dentro de un montaje', () => {
    expect(refusedField(authorization({ workdir: '/etc' }))).toBe('workdir')
  })

  test('una salida declarada vive bajo un montaje de escritura', () => {
    const readOnly = authorization({ mounts: [{ source: ROOT, destination: ROOT, mode: 'ro' }], outputs: [`${ROOT}/out`] })
    expect(refusedField(readOnly)).toBe('outputs')
  })

  test('una autorización vencida se rehúsa', () => {
    expect(refusedField(authorization({ expiresAt: 1000 }), 2000)).toBe('expiresAt')
  })

  test('el dueño se valida', () => {
    expect(refusedField(authorization({ owner: { kind: 'task', id: '', pid: 1 } }))).toBe('owner')
  })

  test('una etiqueta propia no reescribe las de la ejecución', () => {
    expect(refusedField(authorization({ labels: { [EXECUTION_KIND_LABEL_KEY]: 'probe' } }))).toBe('labels')
  })

  test('una variable que nombra una credencial se rehúsa: su valor quedaría en podman inspect', () => {
    expect(() => executionContainerSpec(authorization({ environment: { API_TOKEN: 'x' } }))).toThrow(InvalidExecutionAuthorizationError)
  })
})

describe('el contenedor que materializa una autorización', () => {
  test('lleva tipo, referencia e id en sus etiquetas, su directorio de trabajo, su montaje y su red', () => {
    const argv = createWorkerContainerArgv(executionContainerSpec(authorization()))
    const joined = argv.join(' ')
    expect(argv).toContain(`${EXECUTION_KIND_LABEL_KEY}=test`)
    expect(argv).toContain(`${EXECUTION_REFERENCE_LABEL_KEY}=task:TASK-THYROX-0001`)
    expect(argv).toContain(`${EXECUTION_ID_LABEL_KEY}=test-abc-1`)
    expect(joined).toContain(`--workdir ${ROOT}`)
    expect(joined).toContain(`-v ${ROOT}:${ROOT}:rw`)
    expect(joined).toContain('--network none')
    expect(argv.slice(-2)).toEqual(['bun', 'test'])
  })

  test('el de un modelo publica su puerto en loopback, concede sus dispositivos y lleva sus etiquetas', () => {
    const argv = createWorkerContainerArgv(executionContainerSpec(modelAuthorization()))
    const joined = argv.join(' ')
    expect(argv).toContain(`${EXECUTION_REFERENCE_LABEL_KEY}=grant:g1`)
    expect(argv).toContain('thyrox.model.unit=unit-g1')
    expect(joined).toContain('-p 127.0.0.1:41000:11434')
    expect(joined).toContain('--device nvidia.com/gpu=GPU-1')
    expect(joined).not.toContain('--workdir')
    expect(argv.at(-1)).toBe('docker.io/ollama/ollama:0.35.0')
  })

  test('un secreto se monta como archivo, nunca como variable', () => {
    const argv = createWorkerContainerArgv(executionContainerSpec(authorization({ secrets: [{ name: 'thyrox-x', target: 'x' }] })))
    expect(argv.join(' ')).toContain('--secret thyrox-x,type=mount,target=x')
  })

  test('runExecution corre el contenedor hasta que termina y lo retira', async () => {
    const calls: string[][] = []
    const result = await runExecution(recordingPodman(calls), authorization())
    expect(result.exitCode).toBe(3)
    expect(result.containerId).toBe('c0ffee')
    expect(calls.map(call => call[0])).toEqual(['create', 'start', 'wait', 'logs', 'rm'])
  })

  test('materializeExecution crea, arranca e inspecciona: devuelve la ExecutionUnit canónica y no espera ni retira', async () => {
    const calls: string[][] = []
    const unit = await materializeExecution(recordingPodman(calls, { inspect: INSPECTED }), modelAuthorization(), Date.parse(CREATED_AT))
    expect(unit).toEqual({
      unitId: 'unit-g1',
      kind: 'model-runtime',
      reference: { kind: 'grant', grantId: 'g1' },
      owner: { kind: 'model-coordinator', id: 'coordinator', pid: 7 },
      containerName: 'thyrox-worker-unit-g1',
      containerId: 'c0ffee',
      cgroup: '/machine.slice/libpod-c0ffee.scope',
      hostPids: [9001],
      createdAt: CREATED_AT,
    })
    expect(calls.map(call => call[0])).toEqual(['create', 'start', 'inspect'])
  })

  test('un contenedor sin proceso ni cgroup informado da una unidad sin PIDs ni cgroup', async () => {
    const stopped = { exitCode: 0, stdout: JSON.stringify([{ State: { Pid: 0, CgroupPath: '' } }]), stderr: '' }
    const unit = await materializeExecution(recordingPodman([], { inspect: stopped }), modelAuthorization(), Date.parse(CREATED_AT))
    expect(unit.hostPids).toEqual([])
    expect('cgroup' in unit).toBe(false)
  })

  test('si la inspección falla, nombra la etapa inspect y deja el contenedor a su dueño', async () => {
    const calls: string[][] = []
    const podman = recordingPodman(calls, { inspect: { exitCode: 125, stdout: '', stderr: 'no inspect' } })
    const error = await materializeExecution(podman, modelAuthorization()).catch(caught => caught)
    expect(error).toBeInstanceOf(ContainerRunError)
    expect((error as ContainerRunError).stage).toBe('inspect')
    expect(calls.map(call => call[0])).toEqual(['create', 'start', 'inspect'])
  })

  test('una inspección ilegible también es la etapa inspect, no un éxito sin identidad', async () => {
    const podman = recordingPodman([], { inspect: { exitCode: 0, stdout: 'no es json', stderr: '' } })
    const error = await materializeExecution(podman, modelAuthorization()).catch(caught => caught)
    expect(error).toBeInstanceOf(ContainerRunError)
    expect((error as ContainerRunError).stage).toBe('inspect')
  })

  test('si el arranque falla, materializeExecution nombra la etapa y deja el contenedor a su dueño', async () => {
    const calls: string[][] = []
    const podman = recordingPodman(calls, { start: { exitCode: 125, stdout: '', stderr: 'no start' } })
    const error = await materializeExecution(podman, modelAuthorization()).catch(caught => caught)
    expect(error).toBeInstanceOf(ContainerRunError)
    expect((error as ContainerRunError).stage).toBe('start')
    expect(calls.map(call => call[0])).toEqual(['create', 'start'])
  })

  test('una autorización inválida no llega a Podman', async () => {
    const calls: string[][] = []
    const invalid = authorization({ reference: { kind: 'task', citation: 'nada' } })
    await expect(runExecution(recordingPodman(calls), invalid)).rejects.toThrow(InvalidExecutionAuthorizationError)
    await expect(materializeExecution(recordingPodman(calls), invalid)).rejects.toThrow(InvalidExecutionAuthorizationError)
    expect(calls).toEqual([])
  })
})

/**
 * La verificación como trabajo de la primitiva de Podman (TASK-THYROX-0728).
 *
 * Dos niveles. Con un Podman doble: qué argv compone el trabajo (red,
 * entorno, montajes, ninguna credencial) y cómo se lee su veredicto. Con el
 * Podman real y el registry de prueba en el loopback: que el trabajo
 * materializa y verifica el artefacto sin el almacenamiento de esta sesión.
 *
 * Métrica: el argv entregado a `podman create`, el reporte del montaje y el
 * resultado del verificador.
 * Ciega a: un registry real y su límite anónimo, que mide la publicación
 * de producción, no esta suite.
 */
import { afterEach, beforeEach, describe, expect, test } from 'bun:test'
import { mkdirSync, mkdtempSync, rmSync, writeFileSync } from 'node:fs'
import { tmpdir } from 'node:os'
import { join, resolve } from 'node:path'

import { EXECUTION_ID_LABEL_KEY, EXECUTION_KIND_LABEL_KEY, EXECUTION_REFERENCE_LABEL_KEY } from '@thyrox/podman-execution/executionAuthorization.ts'
import { createPodmanExecutor, type PodmanCommandResult, type PodmanExecutor } from '@thyrox/podman-execution/podmanExecutor.ts'

import { describeArtifactFile } from '../artifactFiles.js'
import { createOciArtifactRegistry } from '../ociArtifactRegistry.js'
import { createPodmanJobVerifier, VERIFICATION_REPORT_NAME, type PodmanJobVerifierOptions } from '../podmanJobVerifier.js'
import { FAKE_PUBLISHER, startFakeOciRegistry, type FakeOciRegistry } from '../testing/fakeOciRegistry.js'

const REPOSITORY_ROOT = resolve(import.meta.dir, '../../../..')
const PINNED = { repository: 'thyrox/lab', digest: 'sha256:' + 'a'.repeat(64) }
const LOCATION = { repository: 'thyrox/lab', tag: 'v1' }

let workdir: string
beforeEach(() => { workdir = mkdtempSync(join(tmpdir(), 'podman-job-verifier-')) })
afterEach(() => { rmSync(workdir, { recursive: true, force: true }) })

function options(overrides: Partial<PodmanJobVerifierOptions> = {}): PodmanJobVerifierOptions {
  return {
    podman: { run: async () => ({ exitCode: 0, stdout: '', stderr: '' }) },
    image: 'sha256:' + 'b'.repeat(64),
    bunPath: process.execPath,
    repositoryRoot: REPOSITORY_ROOT,
    scratchDir: join(workdir, 'scratch'),
    registryUrl: 'https://registry.example',
    egress: { kind: 'proxy', proxyUrl: 'http://10.1.2.3:3128', caBundlePath: '/host/ca.crt' },
    owner: { kind: 'pool', id: 'artifact-verify', pid: process.pid },
    workerId: 'artifact-verify-test',
    limits: { cpus: 1, memoryMib: 512, pidsLimit: 64 },
    ...overrides,
  }
}

/**
 * El doble que registra el argv de `podman create`; `wait` sale 0 para que el
 * trabajo se lea entero. El veredicto no importa aquí: lo que se mide es la
 * composición con la que el contenedor se materializa.
 */
function recordingPodman(): { podman: PodmanExecutor; created: string[][] } {
  const created: string[][] = []
  return {
    created,
    podman: {
      run: async (args): Promise<PodmanCommandResult> => {
        if (args[0] === 'create') created.push([...args])
        if (args[0] === 'wait') return { exitCode: 0, stdout: '0\n', stderr: '' }
        return { exitCode: 0, stdout: '', stderr: '' }
      },
    },
  }
}

/** El argv con que `podman create` materializa el trabajo, leído del doble. */
async function createdArgv(overrides: Partial<PodmanJobVerifierOptions> = {}): Promise<string> {
  const recorder = recordingPodman()
  await createPodmanJobVerifier(options({ ...overrides, podman: recorder.podman })).verify(PINNED, LOCATION)
  return (recorder.created[0] ?? []).join(' ')
}

describe('la composición del trabajo', () => {
  test('con proxy: red host, el proxy declarado y el CA montado de sólo lectura', async () => {
    const argv = await createdArgv()
    expect(argv).toContain('--network host')
    expect(argv).toContain('--env HTTPS_PROXY=http://10.1.2.3:3128')
    expect(argv).toContain('--env NODE_EXTRA_CA_CERTS=/certs/ca-bundle.crt')
    expect(argv).toContain('-v /host/ca.crt:/certs/ca-bundle.crt:ro')
    expect(argv).toContain(`-v ${REPOSITORY_ROOT}:/w:ro`)
  })

  test('sin proxy la red es bridge y no se monta ningún CA', async () => {
    const argv = await createdArgv({ egress: { kind: 'direct' } })
    expect(argv).toContain('--network bridge')
    expect(argv).not.toContain('HTTPS_PROXY')
    expect(argv).not.toContain('/certs/')
  })

  test('el trabajo no recibe credencial ni el almacenamiento de Podman', async () => {
    const argv = await createdArgv()
    expect(argv).not.toMatch(/TOKEN|PASSWORD|SECRET|containers\/storage/i)
    expect(argv).toContain(PINNED.digest)
  })
})

